// Service Worker - Generated by Workbox during build
// This is a placeholder; the actual SW will be generated by vite.config.js

const CACHE_NAME = 'garagem-palio-v2';
const STATIC_ASSETS = [
  '/',
  '/index.html',
  '/manifest.webmanifest'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME)
      .then(cache => cache.addAll(STATIC_ASSETS))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(
        keys.filter(key => key !== CACHE_NAME)
          .map(key => caches.delete(key))
      ))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  if (new URL(event.request.url).origin !== location.origin) return;

  event.respondWith(
    caches.match(event.request, { ignoreSearch: true })
      .then(response => {
        if (response) return response;
        return fetch(event.request)
          .then(networkResponse => {
            const cloned = networkResponse.clone();
            caches.open(CACHE_NAME).then(cache => cache.put(event.request, cloned));
            return networkResponse;
          })
          .catch(() => caches.match('/index.html'));
      })
  );
});

// Background sync for GitHub
self.addEventListener('sync', event => {
  if (event.tag === 'github-sync') {
    event.waitUntil(syncToGitHub());
  }
});

async function syncToGitHub() {
  // This would be implemented with IndexedDB for offline queue
  console.log('Background sync triggered');
}